export const WEB_APP_URL = import.meta.env.VITE_WEB_APP_URL || "http://localhost:3000";

const DEV_ORIGIN = "http://localhost:3000";

function originOf(url: string): string | null {
  try {
    return new URL(url).origin;
  } catch {
    return null;
  }
}

// Origins allowed to request tab data through the content-script bridge. The
// production origin is the one the extension was built with (VITE_WEB_APP_URL);
// the manifest generated by scripts/copy-manifest.mjs injects the same origin.
export const ALLOWED_WEB_ORIGINS: ReadonlySet<string> = new Set(
  [originOf(WEB_APP_URL), DEV_ORIGIN].filter((o): o is string => Boolean(o)),
);

export function isAllowedWebOrigin(origin: string | undefined | null): boolean {
  return Boolean(origin) && ALLOWED_WEB_ORIGINS.has(origin as string);
}
